INSERT INTO `company_profile` (`id`, `setting_key`, `setting_value`, `updated_at`) VALUES
('1', 'main_profile', '{\n  \"company_name\": \"PT Montana Global Investama\",\n  \"short_name\": \"MGI\",\n  \"group_name\": \"Montana Group\",\n  \"tagline_id\": \"Tumbuh Bersama Melalui Investasi Terpercaya\",\n  \"tagline_en\": \"Growing Together Through Trusted Investments\",\n  \"founded_year\": \"2022\",\n  \"kantor_operasional\": \"Roseville Soho & Suite, Sunburst CBD Lot I.8, Jl. Kapten Soebijanto Djojohadikusumo, Lengkong Gudang, Serpong, Tangerang Selatan\",\n  \"headquarters\": \"Roseville Soho & Suite, Sunburst CBD Lot I.8, Jl. Kapten Soebijanto Djojohadikusumo, Lengkong Gudang, Serpong, Tangerang Selatan\",\n  \"stats\": [\n    {\n      \"label\": \"Pendanaan Armada\",\n      \"value\": \"Rp 100M+\",\n      \"desc\": \"Aset Fisik Produktif\"\n    },\n    {\n      \"label\": \"Armada Alat Berat\",\n      \"value\": \"125+ Unit\",\n      \"desc\": \"CBU Siap Operasi\"\n    },\n    {\n      \"label\": \"Fasilitas Sentral\",\n      \"value\": \"4.500 m²\",\n      \"desc\": \"Pool & Workshop Kebumen\"\n    },\n    {\n      \"label\": \"Ekosistem Usaha\",\n      \"value\": \"3 Pilar\",\n      \"desc\": \"MIU, MSI & Mypurcase\"\n    }\n  ],\n  \"about_group\": {\n    \"title\": \"Tentang Montana Group\",\n    \"subtitle\": \"Kelompok Usaha Sektor Riil Berdaya Saing Tinggi & Berkelanjutan\",\n    \"description\": \"Montana Group adalah kelompok usaha yang dipimpin oleh PT Montana Global Investama (MGI) selaku grup dan manajer investasi project, yang menaungi tiga pilar usaha operasional teruji di lapangan. Model ini memungkinkan MGI berfokus pada tata kelola, alokasi modal per project, dan manajemen risiko tingkat grup, sementara setiap unit usaha menjalankan eksekusi operasional sesuai bidang keahliannya masing-masing.\",\n    \"positioning\": \"Dengan struktur grup ini, PT Montana Global Investama memposisikan diri sebagai wadah investasi per project terpercaya bagi pemodal yang ingin berpartisipasi pada pertumbuhan sektor riil (khususnya alat berat, industri logistik, dan rantai ketersediaan pengadaan) melalui satu pintu masuk project investasi yang dikelola secara profesional, transparan, dan berlandaskan kerangka tata kelola TARIF.\"\n  },\n  \"entities\": [\n    {\n      \"code\": \"MGI\",\n      \"name\": \"PT Montana Global Investama\",\n      \"slogan\": \"Tumbuh Bersama Melalui Investasi Terpercaya\",\n      \"role\": \"Manajer Project Investasi & Grup (Tata Kelola, Alokasi Modal Per Project, Manajemen Risiko)\",\n      \"level\": \"Level 0 (Grup)\",\n      \"badge\": \"Grup & Manajer Proyek Investasi\",\n      \"color\": \"gold\",\n      \"description\": \"PT Montana Global Investama berperan sebagai grup dan manajer project investasi (tata kelola, alokasi modal per project, manajemen risiko), menghadirkan instrumen investasi per project sektor riil berbasis aset fisik bernilai tinggi dengan proyeksi pengembalian modal 2-3 tahun.\",\n      \"focus\": \"Pengelolaan portofolio investasi per project, tata kelola TARIF, mitigasi risiko, hubungan investor\",\n      \"output\": \"Alokasi modal per project terukur, kepatuhan laporan berkala, monitoring kinerja proyek\"\n    },\n    {\n      \"code\": \"MIU\",\n      \"name\": \"PT Montana Indo Utama (MIU)\",\n      \"slogan\": \"Solusi Alat Berat Terintegrasi\",\n      \"role\": \"Solusi Alat Berat Terintegrasi — Penjualan, Ketersediaan Armada, Penempatan & Dukungan Operasional\",\n      \"level\": \"Level 1 (Unit Usaha)\",\n      \"badge\": \"Alat Berat & Dukungan Operasional\",\n      \"color\": \"blue\",\n      \"description\": \"Solusi Alat Berat Terintegrasi. Mendukung kebutuhan armada alat berat melalui ketersediaan, penempatan, dan dukungan teknis operasional untuk proyek sektor riil.\",\n      \"focus\": \"Penjualan & suplai unit alat berat, penempatan ke lokasi proyek, perawatan berkala, workshop sentral Kebumen, dan dukungan operasional sektor riil\",\n      \"output\": \"Ketersediaan armada unit alat berat siap kerja, keandalan operasional lapangan, servis darurat siaga, dan kepastian produktivitas proyek\",\n      \"location\": \"Jl. Nasional III No.88, Pejuritan, Kec. Karanganyar, Kab. Kebumen, Jawa Tengah\"\n    },\n    {\n      \"code\": \"MSI\",\n      \"name\": \"PT Montana Sentra Industri (MSI)\",\n      \"slogan\": \"Mitra Impor & Logistik Terpadu\",\n      \"role\": \"Mitra Impor & Logistik — Solusi Impor Alat Berat, Pengurusan Bea Cukai & Distribusi Langsung\",\n      \"level\": \"Level 1 (Unit Usaha)\",\n      \"badge\": \"Mitra Impor & Logistik\",\n      \"color\": \"navy\",\n      \"description\": \"Mitra Impor & Logistik. Menyediakan solusi impor alat berat, pengurusan kepabeanan, dan distribusi langsung ke lokasi proyek untuk kebutuhan industri.\",\n      \"focus\": \"Solusi pengadaan impor alat berat, pengurusan kepabeanan pelabuhan terpadu, dan manajemen pengiriman logistik langsung ke lokasi proyek dan industri\",\n      \"output\": \"Kelancaran izin impor kepabeanan, kepastian ketersediaan armada internasional, efisiensi rantai distribusi, dan pengiriman aman tepat waktu\",\n      \"location\": \"Jl. Revolusi No. 89, Desa/Kelurahan Karanganyar, Kec. Karanganyar, Kab. Kebumen, Provinsi Jawa Tengah\"\n    },\n    {\n      \"code\": \"Mypurcase\",\n      \"name\": \"Mypurcase (Segera Diluncurkan 2027)\",\n      \"slogan\": \"Platform Pengadaan Digital B2B\",\n      \"role\": \"Platform Pengadaan Digital — Penghubung Pembelian, Pemasok, Pengadaan & Rantai Ketersediaan\",\n      \"level\": \"Level 1 (Platform Pengadaan)\",\n      \"badge\": \"Platform Pengadaan B2B\",\n      \"color\": \"gold\",\n      \"description\": \"Platform Pengadaan B2B yang menghubungkan kebutuhan pembelian dengan pemasok terverifikasi, proses pengadaan, dan rantai ketersediaan secara digital, efisien, dan transparan.\",\n      \"focus\": \"Digitalisasi pengadaan B2B, integrasi kebutuhan pembelian dengan pemasok terverifikasi, otomatisasi alur pembelian, dan transparansi rantai ketersediaan\",\n      \"output\": \"Proses pengadaan digital cepat dan transparan, efisiensi belanja modal, pelacakan transaksi langsung, dan tata kelola akuntabel\"\n    }\n  ],\n  \"sections\": [\n    {\n      \"type\": \"text\",\n      \"id\": \"tentang-kami\",\n      \"title\": \"Tentang Kami\",\n      \"subtitle\": \"Membangun Masa Depan Melalui Sinergi Investasi Produktif\",\n      \"content\": \"PT Montana Global Investama (MGI) berperan sebagai grup & manajer investasi (tata kelola, alokasi modal, manajemen risiko), sementara eksekusi operasional dijalankan oleh tiga unit usaha teruji di lapangan: PT Montana Indo Utama, PT Montana Sentra Industri, dan Mypurcase.\",\n      \"quote\": \"Di Montana Global Investama, setiap keputusan investasi berlandaskan pada tiga prinsip utama: aset yang nyata dan terukur, tata kelola yang transparan dan akuntabel, serta kemitraan strategis yang menciptakan nilai berkelanjutan.\"\n    },\n    {\n      \"type\": \"vision_mission\",\n      \"id\": \"visi-misi\",\n      \"title\": \"Visi & Misi Perusahaan\",\n      \"subtitle\": \"Arah Strategis Menuju Keunggulan Pengelolaan Modal Terpercaya\",\n      \"vision\": \"Menjadi perusahaan pengelolaan dana investasi terpercaya di Indonesia yang menghubungkan modal strategis dengan potensi sektor riil bernilai tinggi secara berkesinambungan.\",\n      \"missions\": [\n        \"Mengalokasikan permodalan secara tepat guna pada aset fisik produktif bernilai tinggi dengan perlindungan legal dan asuransi.\",\n        \"Membangun kemitraan strategis offtake jangka menengah hingga panjang untuk menjamin kepastian penyerapan unit proyek.\",\n        \"Menerapkan prinsip tata kelola yang baik secara konsisten melalui kerangka TARIF dalam setiap keputusan dan alokasi modal.\",\n        \"Mengoptimalkan sinergi ekosistem (MGI, MIU, MSI, Mypurcase) untuk menciptakan efisiensi biaya dan perlindungan nilai terintegrasi.\",\n        \"Memberikan transparansi dan pelaporan kinerja berkala demi menjaga akuntabilitas dan kepercayaan mitra pemodal.\"\n      ]\n    },\n    {\n      \"type\": \"cards\",\n      \"id\": \"core-values\",\n      \"title\": \"Nilai-Nilai Perusahaan\",\n      \"subtitle\": \"Fondasi Moral & Profesional Dalam Setiap Pengambilan Keputusan\",\n      \"items\": [\n        {\n          \"icon\": \"shield-check\",\n          \"img\": \"assets/img/icon-tata-kelola.png\",\n          \"name\": \"Integritas\",\n          \"desc\": \"Menjunjung tinggi kejujuran, etika bisnis luhur, dan keterbukaan dalam setiap transaksi dan kemitraan.\"\n        },\n        {\n          \"icon\": \"award\",\n          \"img\": \"assets/img/icon-imbal-hasil.png\",\n          \"name\": \"Profesionalisme\",\n          \"desc\": \"Didukung tim ahli berpengalaman dengan dedikasi tinggi terhadap standar eksekusi terbaik di industri.\"\n        },\n        {\n          \"icon\": \"eye\",\n          \"img\": \"assets/img/icon-transparansi.png\",\n          \"name\": \"Transparansi\",\n          \"desc\": \"Penyajian laporan kinerja berkala, audit independen, dan visibilitas alokasi modal secara menyeluruh kepada investor.\"\n        },\n        {\n          \"icon\": \"gear-wide-connected\",\n          \"img\": \"assets/img/icon-kemitraan.png\",\n          \"name\": \"Kemitraan Strategis\",\n          \"desc\": \"Membangun ekosistem terintegrasi melalui kepastian kerja sama dan kontrak jangka menengah hingga panjang.\"\n        },\n        {\n          \"icon\": \"people\",\n          \"img\": \"assets/img/icon-alokasi-modal.png\",\n          \"name\": \"Sinergi Ekosistem\",\n          \"desc\": \"Menciptakan sinergi erat lintas entitas (MIU, MSI, Mypurcase, MGI) guna memaksimalkan penciptaan nilai kolektif.\"\n        }\n      ]\n    },\n    {\n      \"type\": \"gcg\",\n      \"id\": \"tata-kelola\",\n      \"title\": \"Tata Kelola sebagai Fondasi Kepercayaan\",\n      \"subtitle\": \"Prinsip tata kelola yang baik, transparan, akuntabel, dan terukur diterapkan secara konsisten melalui kerangka TARIF dalam setiap proses pengambilan keputusan dan alokasi modal.\",\n      \"items\": [\n        {\n          \"code\": \"T\",\n          \"name\": \"Transparency\",\n          \"desc\": \"Keterbukaan informasi material dan relevan kepada seluruh pemangku kepentingan.\",\n          \"icon\": \"eye\",\n          \"img\": \"assets/img/icon-transparansi.png\"\n        },\n        {\n          \"code\": \"A\",\n          \"name\": \"Accountability\",\n          \"desc\": \"Kejelasan fungsi, struktur, sistem, dan pertanggungjawaban pengelolaan investasi.\",\n          \"icon\": \"clipboard-check\",\n          \"img\": \"assets/img/icon-tata-kelola.png\"\n        },\n        {\n          \"code\": \"R\",\n          \"name\": \"Responsibility\",\n          \"desc\": \"Kepatuhan penuh terhadap hukum, regulasi, dan tanggung jawab sosial-lingkungan.\",\n          \"icon\": \"people\",\n          \"img\": \"assets/img/icon-kemitraan.png\"\n        },\n        {\n          \"code\": \"I\",\n          \"name\": \"Independency\",\n          \"desc\": \"Pengambilan keputusan profesional objektif bebas dari benturan kepentingan.\",\n          \"icon\": \"balance\",\n          \"img\": \"assets/img/icon-alokasi-modal.png\"\n        },\n        {\n          \"code\": \"F\",\n          \"name\": \"Fairness\",\n          \"desc\": \"Perlakuan adil dan setara bagi seluruh investor dalam pemenuhan hak-hak pemodal.\",\n          \"icon\": \"equal\",\n          \"img\": \"assets/img/icon-imbal-hasil.png\"\n        }\n      ]\n    }\n  ],\n  \"contact\": {\n    \"corporate_office\": \"Roseville Soho & Suite, Sunburst CBD Lot I.8, Jl. Kapten Soebijanto Djojohadikusumo, Lengkong Gudang, Serpong, Tangerang Selatan\",\n    \"operational_office\": \"Jl. Nasional III No.88, Pejuritan, Kec. Karanganyar, Kab. Kebumen, Jawa Tengah\",\n    \"email\": \"kontak@montanaglobalinvestama.com\",\n    \"work_hours\": \"Senin – Jumat: 08.00 – 17.00 WIB\",\n    \"google_maps_url\": \"https://maps.google.com/?q=Roseville+Soho+Sunburst+CBD+Serpong+Tangerang+Selatan\"\n  }\n}', '2026-10-02 09:47:44');

