('mypurcase', 'Mypurcase (Segera Diluncurkan 2027)', 'Mypurcase', NULL, 'mgi-holding', '1', 'Segera Diluncurkan 2027', 'subsidiary', 'Sistem & Pengadaan Terpadu Digital', 'cart-check', 'Sistem dan platform pengadaan terpadu untuk pembelian unit dan mesin secara efisien, transparan, dan terukur lintas entitas dalam ekosistem Montana Group.', '4', '2026-10-05 11:47:31'),
