-- Dumping data for table `project_details`
INSERT INTO `project_details` (`id`, `project_id`, `tagline`, `what_will_provide_title`, `what_will_provide_content`, `sinergi_title`, `sinergi_content`, `summary_title`, `summary_content`, `rab_executive_json`, `created_at`, `updated_at`) VALUES
('1', 'proj-jkt-jabar', 'Kemitraan Strategis Pengadaan Armada Alat Berat CBU Jepang Wilayah Jabodetabek', 'Alokasi Penggunaan Modal Proyek (Pengadaan 25 Unit Alat Berat)', 'Permodalan dialokasikan untuk pengadaan armada unit alat berat siap operasi sebanyak 25 unit (6.25 Kontainer 40FT HC), pengerjaan rekondisi komprehensif di Central Workshop PT Montana Indo Utama, serta penanganan logistik impor door-to-door oleh PT Montana Sentra Industri guna memenuhi tingginya permintaan sektor infrastruktur dan industri regional Jabodetabek.', 'Kerangka Kemitraan Strategis & Penyerapan Pasar (Offtake Framework)', 'Pengadaan unit ini didukung oleh ekosistem Montana Group: PT Montana Sentra Industri (PT MSI) menangani logistik maritim internasional dan izin kepabeanan, sementara PT Montana Indo Utama (PT MIU) menangani workshop rekondisi teknis, offtake pemasaran langsung kepada kontraktor rekanan, serta penyediaan fasilitas operator profesional.', 'Ringkasan Kelayakan Investasi & Profil Risiko', 'Proyek investasi armada alat berat di Jabodetabek menawarkan struktur permodalan terukur dengan proteksi aset riil fisik. Dengan model perputaran modal 2–3 kali per tahun dan efisiensi logistik kontainer 40FT HC, investor menikmati proyeksi imbal hasil bersih tahunan sebesar 28,6% – 42,9% p.a.', '{\"spesifikasi\":{\"barang\":\"Unit Alat Berat\",\"minimum_investasi\":15000000000,\"minimum_tiket\":15000000000,\"periode_investasi\":\"12 Bulan\",\"target_perputaran\":\"2 \\u2013 3 Kali per Tahun\",\"sistem_penjualan\":\"Door to Door via PT MIU\",\"estimasi_unit\":\"25 Unit\",\"container_used\":\"40FT HC Door-to-Door (MSI)\",\"kapasitas_container\":\"4 Unit \\/ Container\",\"catatan\":\"25 unit merupakan alokasi tahap awal dari dana investasi Rp 15.000.000.000 (modal operasional Rp 14.437.500.000); sisa dana Rp 562.500.000 dialokasikan sebagai dana pencadangan pada awal project. Rincian perhitungan pada bagian berikut.\",\"model_kemitraan\":\"Eksklusif (Exclusive Partnership)\",\"kebutuhan_modal_range\":\"Pilihan Paket: Rp 15.000.000.000\",\"fasilitas_operator\":\"Bonus 2 Operator Profesional Resmi MGI\"},\"alokasi_dana\":{\"modal_operasional_label\":\"Modal Operasional Awal (Pengadaan 25 Unit)\",\"modal_operasional_awal\":14437500000,\"dana_pencadangan_label\":\"Dana Pencadangan \\/ Likuiditas (3,75%)\",\"dana_pencadangan\":562500000,\"total_investasi\":15000000000,\"catatan\":\"catatan: Modal operasional awal = (Harga Pokok Pembelian + Alokasi Container + Ongkos Rekondisi) x 25 Unit = (Rp500.000.000 + Rp52.500.000 + Rp25.000.000) x 25 = Rp 14.437.500.000. Komponen PPN, budget garansi, budget insentif, dan fee successful sale (MIU) baru timbul saat unit terjual dan dibayar dari hasil penjualan, sehingga tidak dibebankan pada dana investasi awal. Sisa dana Rp 562.500.000 (3,75% dari total investasi) menjadi dana pencadangan\\/likuiditas project untuk kebutuhan operasional pada tahap awal.\"},\"struktur_biaya_unit\":{\"harga_pokok_beli\":500000000,\"ppn_11\":86414414,\"ongkos_rekondisi\":25000000,\"container_alokasi\":52500000,\"budget_garansi\":8720000,\"budget_insentif\":8720000,\"fee_miu\":104640000,\"total_biaya_unit\":786004414,\"harga_jual_unit\":872000000,\"profit_bersih_unit\":85995586,\"return_per_siklus\":14.33},\"package_options_mode\":\"1\",\"package_options\":[{\"nominal\":15000000000,\"nominal_display\":\"Rp 15.000.000.000\",\"label\":\"Paket Kemitraan Tunggal (15 Miliar)\",\"badge\":\"Bonus 2 Operator Profesional (Double Shift)\",\"featured\":true,\"unit_qty\":25,\"container_qty\":\"6.25 Kontainer 40FT HC (25 Unit)\",\"porsi_proyek\":\"Alokasi Penuh Batch Regional (25 Unit)\",\"jaminan_aset\":\"Seluruh 25 Unit Fisik Alat Berat Siap Operasi\",\"operator_perk\":\"2 Operator Profesional Alat Berat Bersertifikat (Rotasi Shift & Pengawasan)\",\"deskripsi\":\"Penempatan modal penuh Rp 15.000.000.000 untuk mendanai kapasitas penuh proyek regional Jabodetabek (25 Unit Alat Berat) dengan fasilitas Operator resmi MGI yang disediakan dan dikelola langsung oleh tim operasional PT Montana Indo Utama (MIU) untuk memastikan kesiapan unit di lapangan tanpa repot manajemen operasional harian.\",\"profit_per_siklus\":2146200000,\"profit_2x_tahunan\":4292400000,\"profit_3x_tahunan\":6438600000}],\"tiers\":[{\"nominal\":15000000000,\"nominal_display\":\"Rp 15.000.000.000\",\"label\":\"Paket Kemitraan Tunggal (15 Miliar)\",\"badge\":\"Bonus 2 Operator Profesional (Double Shift)\",\"featured\":true,\"unit_qty\":25,\"container_qty\":\"6.25 Kontainer 40FT HC (25 Unit)\",\"porsi_proyek\":\"Alokasi Penuh Batch Regional (25 Unit)\",\"jaminan_aset\":\"Seluruh 25 Unit Fisik Alat Berat Siap Operasi\",\"operator_perk\":\"2 Operator Profesional Alat Berat Bersertifikat (Rotasi Shift & Pengawasan)\",\"deskripsi\":\"Penempatan modal penuh Rp 15.000.000.000 untuk mendanai kapasitas penuh proyek regional Jabodetabek (25 Unit Alat Berat) dengan fasilitas Operator resmi MGI yang disediakan dan dikelola langsung oleh tim operasional PT Montana Indo Utama (MIU) untuk memastikan kesiapan unit di lapangan tanpa repot manajemen operasional harian.\",\"profit_per_siklus\":2146200000,\"profit_2x_tahunan\":4292400000,\"profit_3x_tahunan\":6438600000}],\"operator_perk\":\"2 Operator Profesional Alat Berat Bersertifikat (Rotasi Shift & Pengawasan)\",\"alur_project\":[{\"step\":1,\"title\":\"Pengadaan CBU Jepang\",\"desc\":\"Pembelian unit alat berat langsung dari lelang & mitra terpercaya dengan standar seleksi Grade A.\"},{\"step\":2,\"title\":\"Logistik Laut (PT MSI)\",\"desc\":\"Pengangkutan laut menggunakan kontainer 40FT HC (kapasitas 4 unit\\/kontainer) door-to-door hingga ke pelabuhan domestik dan izin impor lengkap.\"},{\"step\":3,\"title\":\"Rekondisi Workshop (PT MIU)\",\"desc\":\"Inspeksi 100 titik, peremajaan hidrolik, overhaul mesin, pengecatan ulang, dan uji beban kerja di Central Workshop PT Montana Indo Utama.\"},{\"step\":4,\"title\":\"Penjualan Pasar Nasional\",\"desc\":\"Pemasaran unit siap kerja langsung ke end-user (kontraktor tambang, infrastruktur, perkebunan) dengan offtake & garansi resmi 1%.\"},{\"step\":5,\"title\":\"Bagi Hasil Pemodal\",\"desc\":\"Pengembalian modal pokok per unit dan pencairan bagi hasil bersih investor (14,31% per siklus atau 28,6% \\u2013 42,9% disetahunkan).\"}],\"breakdown_pembayaran_unit\":[{\"no\":1,\"komponen\":\"Harga Beli Unit + Ongkos Rekondisi Workshop\",\"penerima\":\"PT MIU\",\"nominal\":525000000,\"keterangan\":\"HPP Pembelian unit (Rp 500 jt) + jasa rekondisi & overhaul standar operasional (Rp 25 jt)\"},{\"no\":2,\"komponen\":\"Ongkos Kontainer 40FT HC Door-to-Door\",\"penerima\":\"PT MSI\",\"nominal\":52500000,\"keterangan\":\"Alokasi per unit (Rp 210.000.000 per 1 kontainer 40FT HC yang memuat 4 unit alat berat)\"},{\"no\":3,\"komponen\":\"Dana Pencadangan \\/ Likuiditas Kas Operasional (3,75%)\",\"penerima\":\"Kas Cadangan\",\"nominal\":22500000,\"keterangan\":\"Buffer likuiditas proyek tahap awal (3,75% dari total investasi) untuk kelancaran operasional sebelum unit terjual\"}],\"total_miu_per_unit\":525000000,\"total_msi_per_unit\":52500000,\"dana_cadangan_per_unit\":22500000,\"total_biaya_per_unit\":600000000}', '2026-10-06 13:27:04', '2026-10-06 13:27:04'),
('2', 'proj-denpasar', 'Kemitraan Strategis Pengadaan Armada Alat Berat CBU Jepang Wilayah Denpasar', 'Alokasi Penggunaan Modal Proyek (Pengadaan 8 Unit Alat Berat)', 'Permodalan dialokasikan untuk pengadaan armada unit alat berat siap operasi sebanyak 8 unit (2 Kontainer 40FT HC), pengerjaan rekondisi komprehensif di Central Workshop PT Montana Indo Utama, serta penanganan logistik impor door-to-door oleh PT Montana Sentra Industri guna memenuhi tingginya permintaan sektor infrastruktur dan industri regional Denpasar.', 'Kerangka Kemitraan Strategis & Penyerapan Pasar (Offtake Framework)', 'Pengadaan unit ini didukung oleh ekosistem Montana Group: PT Montana Sentra Industri (PT MSI) menangani logistik maritim internasional dan izin kepabeanan, sementara PT Montana Indo Utama (PT MIU) menangani workshop rekondisi teknis, offtake pemasaran langsung kepada kontraktor rekanan, serta penyediaan fasilitas operator profesional.', 'Ringkasan Kelayakan Investasi & Profil Risiko', 'Proyek investasi armada alat berat di Denpasar menawarkan struktur permodalan terukur dengan proteksi aset riil fisik. Dengan model perputaran modal 2–3 kali per tahun dan efisiensi logistik kontainer 40FT HC, investor menikmati proyeksi imbal hasil bersih tahunan sebesar 28,6% – 42,9% p.a.', '{\"spesifikasi\":{\"barang\":\"Unit Alat Berat\",\"minimum_investasi\":5000000000,\"minimum_tiket\":5000000000,\"periode_investasi\":\"12 Bulan\",\"target_perputaran\":\"2 \\u2013 3 Kali per Tahun\",\"sistem_penjualan\":\"Door to Door via PT MIU\",\"estimasi_unit\":\"8 Unit\",\"container_used\":\"40FT HC Door-to-Door (MSI)\",\"kapasitas_container\":\"4 Unit \\/ Container\",\"catatan\":\"8 unit merupakan alokasi tahap awal dari dana investasi Rp 5.000.000.000 (modal operasional Rp 4.620.000.000); sisa dana Rp 380.000.000 dialokasikan sebagai dana pencadangan pada awal project. Rincian perhitungan pada bagian berikut.\",\"model_kemitraan\":\"Eksklusif (Exclusive Partnership)\",\"kebutuhan_modal_range\":\"Pilih